import { Component, h, Element } from '@stencil/core';

@Component({
  tag: 'std-dynamic',
  styleUrl: 'std-dynamic.css',
  shadow: true
})
export class MyDynamicAttributes {
  @Element() el: HTMLElement;

  private dynamicAttributes: { [key: string]: string } = {};

  componentWillLoad() {
    const attributes = this.el.getAttributeNames();
    attributes.forEach(attr => {
      if (!this.isDeclaredProp(attr)) {
        this.dynamicAttributes[attr] = this.el.getAttribute(attr);
      }
    });
  }

  private isDeclaredProp(attr: string): boolean {
    const declaredProps = ['prop1', 'prop2'];
    return declaredProps.includes(attr);
  }

  render() {
    return (
      <div>
        <p>Atributos dinámicos:</p>
        <ul>
          {Object.keys(this.dynamicAttributes).map(key => (
            <li>
              {key}: {this.dynamicAttributes[key]}
            </li>
          ))}
        </ul>
      </div>
    );
  }
}
