import { Component, Method, Prop, State, h } from '@stencil/core';

@Component({
  tag: 'std-collapse-list',
  styleUrl: 'std-collapse-list.css',
  shadow: true
})
export class StdCollapseListComponent {
  @Prop() label: string;
  @Prop() icon: string;
  @Prop() tooltipPosition: string;
  @Prop() tooltip: string;
  @Prop() chevron: boolean;
  @Prop() isActive: boolean;
  @Prop({
    mutable: true
  })
  isOpen: boolean;
  @State() showLabel = true;

  @Method()
  async toogleLabel(status?: boolean) {
    this.showLabel = status === undefined ? !this.showLabel : status;
  }

  toggleCollapse(): void {
    this.isOpen = !this.isOpen;
  }

  render() {
    const iconClasses = ['text-primary cursor-pointer text-2xl leading-none', `icon-${this.icon}`].join(' ').trim();

    return (
      <div class={`flex flex-col w-full css-collapse js-collapse ${this.isOpen ? 'is-open' : ''} hover:cursor-pointer ${this.isActive ? 'is-active' : ''}`}>
        <div
          class="collapse-list-header css-collapse-header flex items-center justify-between js-collapse-header border-b border-alternative-medium px-4 py-2 relative group hover:border-dark"
          onClick={() => this.toggleCollapse()}>
          <div class="flex items-center gap-3 lg:collapse-list group">
            <i class={iconClasses}></i>
            {this.showLabel && <p class="text-dark font-normal collapse-list-title whitespace-nowrap">{this.label}</p>}
            <div class="hidden show-collapse group-hover:block">
              {!this.showLabel && (
                <std-tooltip position={this.tooltipPosition} classes="group-hover:block !p-6 !w-auto whitespace-nowrap css-tooltips">
                  {this.label}
                </std-tooltip>
              )}
            </div>
          </div>
          {this.chevron && <i class="icon-chevron-right lg:rotate-90 text-dark cursor-pointer text-2xl" />}
        </div>
        <div class="css-collapse-body js-collapse-body hidden w-full">
          <ol class="flex flex-col w-full list-none">
            <slot />
          </ol>
        </div>
      </div>
    );
  }
}
