// option-list.tsx
import { Component, Prop, h, Event, EventEmitter } from '@stencil/core';

export interface IOptionListItem {
  label: string;
  labelTwo?: string;
  active?: boolean;
}

@Component({
  tag: 'std-option-list',
  styleUrl: 'std-option-list.css',
  shadow: true
})
export class OptionList {
  @Prop() items: IOptionListItem[] = [];

  @Event() itemClicked: EventEmitter<IOptionListItem>;

  handleItemClick(item) {
    this.itemClicked.emit(item);
  }

  render() {
    return (
      <ul class="w-full flex flex-col gap-1 py-1 max-h-[216px] overflow-y-auto">
        {this.items.map(item => (
          <li
            onClick={() => this.handleItemClick(item)}
            class={[
              'flex justify-between items-center gap-2 rounded hover:bg-alternative-light p-3 transition-all duration-300 cursor-pointer',
              item.active ? 'bg-alternative-light font-bold' : ''
            ]
              .join(' ')
              .trim()
              .replace(/\s+/g, ' ')}>
            {item.label && !item.labelTwo && <span class="text-base text-dark">{item.label}</span>}
            {item.labelTwo && (
              <div class="flex flex-col">
                <span class="text-lg text-dark font-headline font-bold">{item.label}</span>
                <span class="text-sm text-dark">{item.labelTwo}</span>
              </div>
            )}
            {item.active && <i class="shrink-0 text-2xl leading-none text-alternative icon-checkmark" />}
          </li>
        ))}
      </ul>
    );
  }
}
