import { Component, h, Prop } from '@stencil/core';

@Component({
  tag: 'std-options-btn',
  styleUrl: 'std-options-btn.css',
  shadow: true
})
export class StdOptionsBtnComponent {
  @Prop() label: string;
  @Prop() href: string;
  @Prop() icon: string;
  @Prop() tooltips: boolean;
  @Prop() tooltipPosition: string;
  @Prop() status: string;
  @Prop() classes: string;

  render() {
    const statusClasses = {
      disabled: 'text-labeldisabled'
    }[this.status];
    const iconClasses = ['i-selector text-2xl leading-none ', `icon-${this.icon}`, statusClasses].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class="h-full flex items-center">
        <a href={this.href} class="flex items-center text-sm leading-5 font-bold whitespace-nowrap cursor-pointer text-alternative">
          <div class="group relative ">
            {this.icon && <i class={iconClasses} />}
            {this.tooltips && (
              <std-tooltip position={this.tooltipPosition} classes="std-options" class="t-selector hidden">
                <slot />
              </std-tooltip>
            )}
            {this.label && <span class={this.classes}>{this.label} </span>}
          </div>
        </a>
      </div>
    );
  }
}
